+    }
+
+    /**
+     * Render a snapshot frame as an HTML fragment with **debug comments** on
+     * every node (see {@link #renderDebug}).
+     */
+    public String renderFragmentDebug(ProtocolFrame frame, int root) {
+        return renderFrameDebug(frame, root, false);
+    }
