+    @Test
+    void debugRenderEmitsNodeCommentsButDefaultDoesNot() {
+        View root = VStack.children(
+                dev.pathland.view.Text.make(t -> t.text("Hello")),
+                dev.pathland.view.Button.make(b -> b.title("Go").action(() -> { })));
+        ProtocolFrame frame = frameOf(root);
