-            T next = fn.get();
-            if (equal.test(cachedValue, next)) {
-                // Same value: keep version, do not propagate to consumers.
-                error = null;
-            } else {
-                cachedValue = next;
-                error = null;
-                version++;
-                propagate();
-            }
-        } catch (Throwable t) {
-            if (!Objects.equals(error, t)) {
-                error = t;
-                version++; // notify consumers so they re-run and observe the error
-                propagate();
-            }
-        } finally {
-            ReactiveContext.pop();
-        }
