+                opcodes.add(new Opcode(
+                        Categories.EVENT, Commands.Event.DATE_CHANGED, 0, event.target(), event.b(), event.c()));
+            } else if (event.isFocusChanged() || event.isEditingChanged() || event.isSubmit()) {
