-        // Without any binding the field resolves to null.
-        seen.clear();
-        new Emitter(sink()).mount(new SidebarLike(), Environment.DEFAULT);
-        assertEquals(1, seen.size());
-        assertEquals(null, seen.get(0), "no binding → the lazy field yields null");
