+        return frame.opcodes().stream()
+                .filter(o -> o.category() == Categories.PARAMETER && o.command() == Commands.Parameter.SET_PROPERTY)
+                .filter(o -> (o.b() & 0xFFFF) == Properties.FIT_QUERY)
+                .findFirst().orElseThrow();
