+/// use std::rc::Rc;
+/// use pathland_engine::{Engine, MediaController};
+///
+/// let engine = Engine::new();
+/// let rt = engine.runtime();
+/// let player = Rc::new(
+///     MediaController::with_source(&rt, "/assets/track1.mp3")
+///         .on_ended(|| { /* next track */ }),
+/// );
+/// player.play();
