 fn emit_and_read_token(engine: &mut Engine, root: &Node) -> (u16, u8, String) {
     let (mut mem, layout) = with_guest();
     {
         let mut guest = Guest::new(&mut mem, &layout);
         guest.begin_frame();
         engine.emit(root, &mut guest).unwrap();
         guest.end_frame();
