+    /// Apply the app's requested playback state (a no-op if unchanged).
+    Play(bool),
+    /// Seek to a position in seconds (a GStreamer FLUSH seek).
+    Seek(f32),
+    /// Set the volume (0..1).
+    Volume(f32),
+    /// Mute/unmute (independent of volume).
+    Muted(bool),
+    /// Loop the resource on end.
