+        single.push(Opcode::new(category::TREE, tree::CREATE_NODE, 0, 1, component_type::SIZE_THAT_FITS as u32, 0));
+        single.push(Opcode::new(category::TREE, tree::INSERT_CHILD, 0, 1, 3, 0));
