+    assert!(host.set_signal(source, SignalValue::Str("/assets/track2.mp3".into())));
+    let delta = host.next_frame().unwrap().expect("a delta frame");
+    let ops: Vec<pathland_core::Opcode> = delta.frame().opcodes().collect();
