     const QByteArray bytes = text.toUtf8();
     PathlandQtEvent ev{};
     ev.kind = PLQT_EV_TEXT_CHANGED;
     ev.node_id = nodeId;
     ev.str_len = static_cast<uint32_t>(bytes.size());
     ev.str = bytes.constData();
     fire(this, ev);
