 int pathland_qt_layer_init(PathlandQtWake wake, PathlandQtTick tick,
                            PathlandQtEventFn event_fn, void *user) {
     Q_UNUSED(wake); // reserved: the shell only wakes on run (the host drains the ring)
     if (g.initialized) {
