    QList<QQuickItem *> siblingsList = attach->childItems();
    siblingsList.removeAll(child);
    if (static_cast<int>(index) < siblingsList.size()) {
        QQuickItem *after = siblingsList.at(static_cast<int>(index));
        if (after != child) {
            child->stackBefore(after);
        }
    }
}

