    PathlandQtEvent ev{};
    ev.kind = static_cast<uint8_t>(kind);
    ev.node_id = nodeId;
    ev.x = static_cast<float>(x);
    ev.y = static_cast<float>(y);
    if (event_fn) {
        event_fn(&ev, user);
    }
}

