    // NAVIGATE is global (never node-keyed), so it is never gated.
    PathlandQtEvent ev{};
    ev.kind = PLQT_EV_NAVIGATE_BACK;
    ev.node_id = 0;
    if (event_fn) {
        event_fn(&ev, user);
    }
}

