                        environmentBinding(e -> e.key(Navigation.ROUTER).value(router)))
                .children(
                        new Sidebar(),
                        ScrollView.make() .modifiers(frame(f -> f.width(Float.POSITIVE_INFINITY)))
                                .children(Navigation.container(router)));
    }

